"site.index.multiogarPrivateServer": "Приватный сервер MultiOgar",
"site.index.readAndApplyThese": "⚠️ ПРОЧИТАЙТЕ И ПРИМЕНИТЕ! ЭТО ВАЖНО ⚠️",
